    {
        return uint32_t( ( id * 0x9E3779B97F4A7C15ull ) >> 55 ) & uint32_t( kBuckets - 1 );
    }

    // the reference an id takes: its message-form SLOT under the connection's
    // table, or the file's own first-use entry
